<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ValueObject\ApiKeyClientKeyVO;

trait ApiKeyClientKeyAttributeHolder
{
    protected ApiKeyClientKeyVO|string|null $key = null;
    protected bool $keyAssigned = false;

    public function getKeyOrCurrent(?ApiKeyClientKeyVO $key): ?ApiKeyClientKeyVO
    {
        return $this->keyAssigned ? ($this->key === null ? null : ApiKeyClientKeyVO::from($this->key)) : $key;
    }
    public function keyTryBuildInitial(ConstraintFailList $error): ?ApiKeyClientKeyVO
    {
        return  ApiKeyClientKeyVO::tryFrom($this->keyAssigned ? $this->key : null, $error);
    }
    public function key(ApiKeyClientKeyVO|string|null $key): static
    {
        $this->key = $key;
        $this->keyAssigned = true;
        return $this;
    }
    public function getKey(): ?string
    {
        return $this->key instanceof ApiKeyClientKeyVO ? $this->key->value() : $this->key;
    }
    public function isKeyAssigned(): bool
    {
        return $this->keyAssigned;
    }
    public function writeKeyTo(mixed $att): void
    {
        if ($this->keyAssigned) {
            $att->key($this->key);
        }
    }
    public function readKeyFrom(mixed $att): void
    {
        if ($att->isKeyAssigned()) {
            $key = $att->getKey();
            $this->key($key);
        }
    }
    public function unsetKey(): static
    {
        $this->keyAssigned = false;
        return $this;
    }
    protected function withDefaultKey(): void
    {
    }
    protected function withAssertedKeyRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->keyAssigned = $this->keyAssigned) {
            $value->key = ApiKeyClientKeyVO::tryFrom($this->key, $errorsList);
        }
    }
}
